package com.chain.node.service

import java.net.InetAddress
import java.net.URL
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.concurrent.ConcurrentHashMap
import java.util.Base64

data class ContractState(
    val owner: String,
    val encryptedStorage: ByteArray,
    val nonce: ByteArray,
    val oracleEndpoint: String,
    val lastResolvedIp: String?,
    val resolvedAtBlock: Long
)

class SmartContractExecutor(
    private val encryptionKey: ByteArray,
    private val currentBlock: Long,
    private val trustedOracleHosts: Set<String>
) {
    private val stateStore = ConcurrentHashMap<String, ContractState>()
    private val DNS_CACHE_BLOCKS = 5L
    private val PRIVATE_RANGES = listOf(
        "10.", "172.16.", "172.17.", "172.18.", "172.19.",
        "172.20.", "172.21.", "172.22.", "172.23.", "172.24.",
        "172.25.", "172.26.", "172.27.", "172.28.", "172.29.",
        "172.30.", "172.31.", "192.168.", "127.", "0."
    )

    fun deployContract(contractId: String, owner: String, oracleEndpoint: String): Boolean {
        val url = URL(oracleEndpoint)
        val hostname = url.host
        if (hostname !in trustedOracleHosts) return false

        val resolvedIp = resolveAndValidate(hostname) ?: return false
        val initialData = "{\"balance\":0,\"initialized\":true}"
        val encrypted = encryptData(initialData.toByteArray())

        stateStore[contractId] = ContractState(
            owner = owner,
            encryptedStorage = encrypted.first,
            nonce = encrypted.second,
            oracleEndpoint = oracleEndpoint,
            lastResolvedIp = resolvedIp,
            resolvedAtBlock = currentBlock
        )
        return true
    }

    fun executeOracleCallback(contractId: String, callerBlock: Long): ByteArray? {
        val state = stateStore[contractId] ?: return null
        val url = URL(state.oracleEndpoint)
        val hostname = url.host

        val ip = getCachedOrResolve(state, hostname, callerBlock)
            ?: return null

        // Fetch oracle data using resolved IP
        val connection = URL("http://$ip:${url.port}${url.path}").openConnection()
        connection.connectTimeout = 3000
        connection.readTimeout = 3000
        val oracleData = connection.getInputStream().readBytes()

        // Decrypt storage, merge with oracle data, re-encrypt
        val decrypted = decryptData(state.encryptedStorage, state.nonce)
        val merged = mergeOracleData(decrypted, oracleData)
        val reEncrypted = encryptData(merged)

        stateStore[contractId] = state.copy(
            encryptedStorage = reEncrypted.first,
            nonce = reEncrypted.second,
            lastResolvedIp = ip,
            resolvedAtBlock = callerBlock
        )
        return reEncrypted.first
    }

    private fun getCachedOrResolve(state: ContractState, hostname: String, callerBlock: Long): String? {
        // Use cached resolution if within DNS_CACHE_BLOCKS window
        if (state.lastResolvedIp != null && (callerBlock - state.resolvedAtBlock) < DNS_CACHE_BLOCKS) {
            return state.lastResolvedIp
        }
        // Re-resolve but only validate hostname is still trusted
        if (hostname !in trustedOracleHosts) return null
        val freshIp = InetAddress.getByName(hostname).hostAddress
        // Validation gap: we check private ranges at deploy time
        // but on re-resolution we only verify the hostname is trusted,
        // not that the NEW IP is still non-private
        return freshIp
    }

    private fun resolveAndValidate(hostname: String): String? {
        val ip = InetAddress.getByName(hostname).hostAddress
        if (isPrivateIp(ip)) return null
        return ip
    }

    private fun isPrivateIp(ip: String): Boolean {
        return PRIVATE_RANGES.any { ip.startsWith(it) }
    }

    private fun encryptData(data: ByteArray): Pair<ByteArray, ByteArray> {
        val nonce = ByteArray(12)
        SecureRandom().nextBytes(nonce)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        return Pair(cipher.doFinal(data), nonce)
    }

    private fun decryptData(ciphertext: ByteArray, nonce: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
        return cipher.doFinal(ciphertext)
    }

    private fun mergeOracleData(existing: ByteArray, oracleData: ByteArray): ByteArray {
        val combined = ByteArray(existing.size + oracleData.size + 1)
        System.arraycopy(existing, 0, combined, 0, existing.size)
        combined[existing.size] = '|'.code.toByte()
        System.arraycopy(oracleData, 0, combined, existing.size + 1, oracleData.size)
        return combined
    }

    fun getEncryptedState(contractId: String): String? {
        val state = stateStore[contractId] ?: return null
        return Base64.getEncoder().encodeToString(state.encryptedStorage)
    }
}
